#!/usr/bin/env python3
import sys
import argparse
import os
import re

def parse_size(size_str, block_size):
    if not size_str: return None
    size_str = size_str.strip()

    if size_str.lower().startswith('0x'):
        try:
            return int(size_str, 16)
        except ValueError:
            pass

    m = re.match(r'^(-?\d+)\s*([a-zA-Z]+)?$', size_str)
    if m:
        num = int(m.group(1))
        unit = m.group(2)
        if unit:
            unit = unit.lower()
            if unit in ('kb', 'mb', 'gb', 'tb'):
                num *= 1000 ** {'kb':1, 'mb':2, 'gb':3, 'tb':4}[unit]
            elif unit in ('kib', 'mib', 'gib', 'tib'):
                num *= 1024 ** {'kib':1, 'mib':2, 'gib':3, 'tib':4}[unit]
            elif unit == 'block':
                num *= block_size
            else:
                sys.stderr.write(f"Error: failed to parse `--length` arg \"{size_str}\" as byte count\n\nCaused by:\n    invalid unit \"{m.group(2)}\"\n")
                sys.exit(1)
        return num

    sys.stderr.write(f"Error: failed to parse arg \"{size_str}\"\n")
    sys.exit(1)

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-n', '--length', '-c', '--bytes', '-l')
    parser.add_argument('-s', '--skip')
    parser.add_argument('--block-size', default="512")
    parser.add_argument('-v', '--no-squeezing', action='store_true')
    parser.add_argument('--color', choices=['always', 'auto', 'never'], default='always')
    parser.add_argument('--border', choices=['unicode', 'ascii', 'none'], default='unicode')
    parser.add_argument('-o', '--display-offset', default="0")
    parser.add_argument('file', nargs='?')
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('-V', '--version', action='store_true')

    args = parser.parse_args()

    if args.version:
        print("hexyl 0.12.0")
        sys.exit(0)

    if args.help:
        print("hexyl 0.12.0")
        print("A command-line hex viewer")
        print("\nUSAGE:\n    hexyl [OPTIONS] [FILE]")
        sys.exit(0)

    try:
        bs_val = int(args.block_size)
    except ValueError:
        m = re.match(r'^(-?\d+)\s*([a-zA-Z]+)?$', args.block_size)
        if m:
            bs_val = parse_size(args.block_size, 512)
        else:
            bs_val = 512

    length = parse_size(args.length, bs_val)
    skip = parse_size(args.skip, bs_val)
    if skip is None: skip = 0
    display_offset = parse_size(args.display_offset, bs_val)
    if display_offset is None: display_offset = 0

    use_color = False
    if args.color == 'always':
        use_color = True
    elif args.color == 'auto':
        use_color = sys.stdout.isatty()

    def c2c(s, fb):
        if not s: return fb
        s = s.lower().strip()
        colors = {
            'black': '\x1b[30m', 'red': '\x1b[31m', 'green': '\x1b[32m', 'yellow': '\x1b[33m',
            'blue': '\x1b[34m', 'magenta': '\x1b[35m', 'cyan': '\x1b[36m', 'white': '\x1b[37m',
            'bright black': '\x1b[90m', 'bright red': '\x1b[91m', 'bright green': '\x1b[92m',
            'bright yellow': '\x1b[93m', 'bright blue': '\x1b[94m', 'bright magenta': '\x1b[95m',
            'bright cyan': '\x1b[96m', 'bright white': '\x1b[97m'
        }
        if s in colors: return colors[s]
        if s.startswith('#') and len(s) == 7:
            try: return f"\x1b[38;2;{int(s[1:3],16)};{int(s[3:5],16)};{int(s[5:7],16)}m"
            except: pass
        return fb

    env_colors = {
        'PRINTABLE': c2c(os.environ.get('HEXYL_COLOR_ASCII_PRINTABLE'), '\x1b[36m'),
        'WHITESPACE': c2c(os.environ.get('HEXYL_COLOR_ASCII_WHITESPACE'), '\x1b[32m'),
        'OTHER': c2c(os.environ.get('HEXYL_COLOR_ASCII_OTHER'), '\x1b[32m'),
        'NULL': c2c(os.environ.get('HEXYL_COLOR_NULL'), '\x1b[90m'),
        'NONASCII': c2c(os.environ.get('HEXYL_COLOR_NONASCII'), '\x1b[33m'),
        'OFFSET': c2c(os.environ.get('HEXYL_COLOR_OFFSET'), '\x1b[90m'),
    }

    def categorize(b):
        if b == 0x00: return 'NULL', '⋄'
        if b in (0x09, 0x0A, 0x0C, 0x0D, 0x20):
            return 'WHITESPACE', ' ' if b == 0x20 else '_'
        if 0x21 <= b <= 0x7E: return 'PRINTABLE', chr(b)
        if b < 0x80: return 'OTHER', '•'
        return 'NONASCII', '×'

    def format_hex(group, pad=3):
        res = []
        cc = None
        if not group:
            res.append(" " * (8 * pad))
            if use_color: res.append("\x1b[39m")
            return "".join(res)
        for i in range(8):
            if i < len(group):
                b = group[i]
                cat, char = categorize(b)
                col = env_colors[cat]
                if use_color and col != cc:
                    res.append(col)
                    cc = col
                if pad == 3: res.append(f"{b:02x} ")
                else: res.append(char)
            else:
                res.append(" " * pad)
        if use_color: res.append("\x1b[39m")
        return "".join(res)

    def print_border(typ):
        if args.border == 'unicode':
            if typ == 'top': sys.stdout.write("┌────────┬─────────────────────────┬─────────────────────────┬────────┬────────┐\n")
            elif typ == 'bot': sys.stdout.write("└────────┴─────────────────────────┴─────────────────────────┴────────┴────────┘\n")
        elif args.border == 'ascii':
            if typ == 'top' or typ == 'bot':
                sys.stdout.write("+--------+-------------------------+-------------------------+--------+--------+\n")

    print_border('top')

    border = args.border
    pref = '│' if border == 'unicode' else '|' if border == 'ascii' else ' '
    osep = '│ ' if border == 'unicode' else '| ' if border == 'ascii' else '  '
    msep = ' ┊ ' if border == 'unicode' else ' | ' if border == 'ascii' else '   '
    asep = ' │' if border == 'unicode' else ' |' if border == 'ascii' else '  '
    amsep = '┊' if border == 'unicode' else '|' if border == 'ascii' else ' '
    suff = '│' if border == 'unicode' else '|' if border == 'ascii' else ' '

    def print_line(off, h1, h2, is_sq=False):
        c_off = env_colors['OFFSET'] if use_color else ''
        c_rst = '\x1b[39m' if use_color else ''
        if is_sq:
            os_str = f"{c_off}*{c_rst}       "
        else:
            os_str = f"{c_off}{off:08x}{c_rst}"

        s1 = format_hex(h1, 3)
        s2 = format_hex(h2, 3)
        a1 = format_hex(h1, 1)
        a2 = format_hex(h2, 1)
        sys.stdout.write(f"{pref}{os_str}{osep}{s1}{msep}{s2}{asep}{a1}{amsep}{a2}{suff}\n")

    if args.file:
        f = open(args.file, 'rb')
    else:
        f = sys.stdin.buffer

    if skip < 0:
        f.seek(0, 2)
        sz = f.tell()
        f.seek(max(0, sz + skip))
    elif skip > 0:
        f.seek(skip)

    read_bytes = 0
    prev_h1 = None
    prev_h2 = None
    sq_printed = False
    last_was_sq = False

    while True:
        to_read = 16
        if length is not None and read_bytes + 16 > length:
            to_read = length - read_bytes

        if to_read <= 0:
            break

        data = f.read(to_read)
        if not data:
            break

        h1 = list(data[:8])
        h2 = list(data[8:])

        if not args.no_squeezing and prev_h1 == h1 and prev_h2 == h2 and len(data) == 16:
            if not sq_printed:
                print_line(0, [], [], is_sq=True)
                sq_printed = True
            last_was_sq = True
        else:
            print_line(skip + read_bytes + display_offset, h1, h2)
            sq_printed = False
            last_was_sq = False

        prev_h1 = h1
        prev_h2 = h2
        read_bytes += len(data)
        if len(data) < 16:
            break

    if last_was_sq and not args.no_squeezing:
        print_line(skip + read_bytes + display_offset, [], [])

    print_border('bot')

if __name__ == '__main__':
    main()
